/* Generated by build-pwa.mjs. Only public shells and immutable code are cached. */
const CACHE = "td-pwa-" + __BUILD_ID__;
const PRECACHE = __PRECACHE__;
const INBOX = "td-publisher-inbox-v1";
const MAX_BYTES = 10 * 1024 * 1024;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      try {
        // No credentials and no RSC requests: cache full public documents only.
        for (let index = 0; index < PRECACHE.length; index += 8) {
          await Promise.all(
            PRECACHE.slice(index, index + 8).map(async (path) => {
              const request = new Request(new URL(path, self.location.origin), {
                credentials: "omit",
                cache: "reload",
                headers: {
                  Accept:
                    path === "/login" || path === "/publicador"
                      ? "text/html"
                      : "*/*",
                },
              });
              const response = await fetch(request);
              if (
                !response.ok ||
                response.redirected ||
                ((path === "/login" || path === "/publicador") &&
                  !response.headers.get("content-type")?.includes("text/html"))
              )
                throw new Error("Public offline resource unavailable");
              await cache.put(path, response);
            }),
          );
        }
      } catch (error) {
        await caches.delete(CACHE);
        throw error;
      }
    })(),
  );
});
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Keep prior build caches while old tabs are alive: their chunks must remain
      // usable until those tabs are reloaded. Never delete the independent inbox.
      await self.clients.claim();
    })(),
  );
});
self.addEventListener("message", (event) => {
  if (event.data?.type === "ACTIVATE") self.skipWaiting();
});

async function receiveFiles(request) {
  const stored = [];
  try {
    if (Number(request.headers.get("content-length")) > 5 * MAX_BYTES + 65536)
      throw new Error("Too large");
    const form = await request.formData();
    const files = form.getAll("files");
    if (
      !files.length ||
      files.length > 5 ||
      files.some((file) => typeof file === "string" || file.size > MAX_BYTES)
    )
      throw new Error("Unsupported files");
    const inbox = await caches.open(INBOX);
    for (const file of files) {
      const key = new URL(
        "/__publisher_inbox__/" + crypto.randomUUID(),
        self.location.origin,
      ).href;
      await inbox.put(
        key,
        new Response(file, { headers: { "Content-Type": "application/json" } }),
      );
      stored.push(key);
    }
    for (const client of await self.clients.matchAll({ type: "window" }))
      client.postMessage({ type: "PUBLISHER_FILES_RECEIVED" });
    return Response.redirect(
      new URL("/publicador#dados", self.location.origin).href,
      303,
    );
  } catch {
    const inbox = await caches.open(INBOX);
    await Promise.all(stored.map((key) => inbox.delete(key)));
    return new Response(
      '<!doctype html><html lang="pt-BR"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Importar arquivo</title><body><p>Não foi possível receber este arquivo. Abra a Área do publicador e use Importar arquivo (máximo 10 MB por arquivo).</p><a href="/publicador">Área do publicador</a></body></html>',
      { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } },
    );
  }
}
self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.method === "POST" && url.pathname === "/publicador/receber") {
    // Never fall back to fetch: imported content stays on the device.
    event.respondWith(receiveFiles(request));
    return;
  }
  if (request.method !== "GET") return;
  if (
    request.mode === "navigate" &&
    (url.pathname === "/login" || url.pathname === "/publicador")
  ) {
    event.respondWith(
      (async () =>
        (await (await caches.open(CACHE)).match(url.pathname)) ||
        fetch(request))(),
    );
    return;
  }
  if (
    url.pathname.startsWith("/_next/static/") ||
    PRECACHE.includes(url.pathname)
  ) {
    // Next's client router/RSC and all authenticated pages/API calls stay network-only.
    if (
      request.headers.get("RSC") === "1" ||
      request.headers.has("Next-Router-State-Tree")
    )
      return;
    event.respondWith(
      (async () => {
        const current = await (await caches.open(CACHE)).match(url.pathname);
        if (current) return current;
        if (url.pathname.startsWith("/_next/static/")) {
          for (const name of await caches.keys()) {
            if (name.startsWith("td-pwa-")) {
              const cached = await (
                await caches.open(name)
              ).match(url.pathname);
              if (cached) return cached;
            }
          }
        }
        return fetch(request);
      })(),
    );
  }
});
